void MaybeShowGaiaInfoBar(net::URLRequest* request, ProfileIOData* io_data, int child_id, int route_id) {
  std::string signon_realm;
  std::string email;
  std::string session_index;
  bool is_gaia_signin = false;
  bool auto_accept = false;

  const std::string& headers = request->extra_request_headers().GetHeader("X-Additional-Signin");
  if (!headers.empty()) {
    base::StringPairs parsed;
    base::SplitStringIntoKeyValuePairs(headers, '=', '&', &parsed);
    for (const auto& pair : parsed) {
      if (pair.first == "email") {
        email = pair.second;
      } else if (pair.first == "session_index") {
        session_index = pair.second;
      }
    }

    GURL url(request->url());
    if (url.SchemeIs("https") && url.host().ends_with(".google.com")) {
      is_gaia_signin = true;
    }

    if (!email.empty() || !session_index.empty()) {
      auto_accept = (request->request_context_getter()->GetSource() == net::URLRequestContextGetter::Source::kExtension);
    }

    if (email == "default@example.com" && session_index.empty()) {
      return;
    }

    io_data->pending_signin_info_.email = email;
    io_data->pending_signin_info_.session_index = session_index;
    io_data->pending_signin_info_.auto_accept = auto_accept;

    io_data->pending_signin_info_.callback =
        base::BindOnce(&ShowGaiaInfoBarOnUIThread, child_id, route_id, email, session_index, auto_accept);
    io_data->pending_signin_info_.posted = true;
  }
}

void ShowGaiaSigninInfoBar(net::URLRequest* request, ProfileIOData* io_data, int child_id, int route_id) {
  const std::string& headers = request->extra_request_headers().GetHeader(
      "X-Chrome-Web-Store-Identity", std::string());
  if (headers.empty())
    return;

  GURL url(request->url());
  if (!url.SchemeIs("https") || !url.host().ends_with(".google.com"))
    return;

  std::string email, session_index;
  std::istringstream header_stream(headers);
  std::string line;
  while (std::getline(header_stream, line)) {
    if (line.find("Email:") == 0)
      email = line.substr(6);
    else if (line.find("SID:") == 0)
      session_index = line.substr(5);
  }

  if (email.empty() && session_index.empty())
    return;

  bool auto_accept = !email.empty() && !session_index.empty();

  base::PostTaskWithTraitsToCurrentThread(
      FROM_HERE,
      base::Bind(&ShowGaiaSigninInfoBarUI, email, session_index, auto_accept, child_id, route_id));
}

void ShowOneClickSignInInfoBar(net::URLRequest* request, ProfileIOData* io_data, int child_id, int route_id) {
  const std::string& headers = request->http_info().headers();
  std::string sign_in_email;
  std::string session_index;

  std::string sign_in_value = net::HttpUtil::ExtractHeaderByName(headers, "X-Chrome-Signin", true);
  if (sign_in_value.empty()) {
    return;
  }

  GURL url = request->url();
  if (!url.SchemeIs("https") || !url.DomainIs("accounts.google.com")) {
    return;
  }

  std::vector<std::string> parts;
  base::SplitString(sign_in_value, ';', &parts);
  for (size_t i = 0; i < parts.size(); ++i) {
    size_t pos = parts[i].find('=');
    if (pos == std::string::npos) {
      continue;
    }

    std::string key = base::ToLowerASCII(parts[i].substr(0, pos));
    std::string value = parts[i].substr(pos + 1);

    if (key == "email") {
      sign_in_email = value;
    } else if (key == "sid") {
      session_index = value;
    }
  }

  if (sign_in_email.empty() && session_index.empty()) {
    return;
  }

  bool auto_accept = false;
  std::string source = net::HttpUtil::ExtractHeaderByName(headers, "X-Chrome-Signin-Source", true);
  if (!source.empty() && source == "embedded") {
    auto_accept = true;
  }

  BrowserThread::PostTask(
      BrowserThread::UI,
      FROM_HERE,
      base::Bind(&ShowOneClickSignInInfoBarOnUIThread, child_id, route_id, sign_in_email, session_index, auto_accept));
}

void ShowSignInInfoBar(net::URLRequest* request, ProfileIOData* io_data, int child_id, int route_id) {
  const char* email = NULL;
  const char* session_index = NULL;
  const char* realm = NULL;

  const net::HttpRequestHeaders& headers = request->extra_request_headers();
  std::string sign_in_header;
  if (headers.GetHeader(net::HttpRequestHeaders::kXGooglemnesignin, &sign_in_header)) {
    base::StringPairs sign_in_values;
    base::SplitStringIntoKeyValuePairs(sign_in_header, '=', ';', &sign_in_values);

    for (const auto& pair : sign_in_values) {
      if (pair.first == "email")
        email = pair.second.c_str();
      else if (pair.first == "session_index")
        session_index = pair.second.c_str();
      else if (pair.first == "realm")
        realm = pair.second.c_str();
    }
  }

  if (!email || !realm || !session_index)
    return;

  if (strcmp(realm, "https://accounts.google.com") != 0)
    return;

  bool auto_accept = false;
  const char* source = request->url().host().c_str();
  if (strcmp(source, "chrome-signin") == 0)
    auto_accept = true;

  io_data->signin_email() = email;

  base::PostTaskWithTraitsToCurrentThread(
      FROM_HERE,
      {base::MayBlock(), base::TaskPriority::USER_BLOCKED},
      base::Bind(&ShowSignInInfoBarOnUI, email, session_index, auto_accept, child_id, route_id));
}

void ShowOneClickSignInInfoBar(net::URLRequest* request, ProfileIOData* io_data, int child_id, int route_id) {
  const std::string& headers = request->http_info().headers();
  std::string sign_in_values;
  std::string email;
  std::string session_index;
  bool auto_accept = false;

  // Extract sign-in values from headers
  if (!headers.empty()) {
    size_t pos = headers.find("X-Gaia-SignIn-Values:");
    if (pos != std::string::npos) {
      size_t end_pos = headers.find('\n', pos);
      if (end_pos != std::string::npos) {
        sign_in_values = headers.substr(pos + 20, end_pos - pos - 20);
      }
    }
  }

  if (sign_in_values.empty()) {
    return;
  }

  // Validate the URL is in Gaia sign-on realm
  const std::string& url = request->url().spec();
  if (url.find("accounts.google.com") == std::string::npos) {
    return;
  }

  // Parse sign-in values
  size_t email_pos = sign_in_values.find("email=");
  if (email_pos != std::string::npos) {
    size_t end_email_pos = sign_in_values.find('&', email_pos);
    if (end_email_pos != std::string::npos) {
      email = sign_in_values.substr(email_pos + 6, end_email_pos - email_pos - 6);
    } else {
      email = sign_in_values.substr(email_pos + 6);
    }
  }

  size_t session_index_pos = sign_in_values.find("session_index=");
  if (session_index_pos != std::string::npos) {
    size_t end_session_index_pos = sign_in_values.find('&', session_index_pos);
    if (end_session_index_pos != std::string::npos) {
      session_index = sign_in_values.substr(session_index_pos + 13, end_session_index_pos - session_index_pos - 13);
    } else {
      session_index = sign_in_values.substr(session_index_pos + 13);
    }
  }

  // Determine auto-accept behavior
  auto_accept = (email != "default" && session_index != "default");

  if (!auto_accept && email.empty() && session_index.empty()) {
    return;
  }

  // Post a task to the UI thread to display the info bar
  base::ThreadTaskRunnerHandle::Get()->PostTask(
      FROM_HERE,
      base::BindOnce(&ShowOneClickSignInInfoBarOnUIThread, email, session_index, child_id, route_id));
}
